<span class="line"><span style="color:#D19A66;">        d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">item_id</span><span style="color:#C678DD;"> AS</span><span style="color:#ABB2BF;"> parent_item_id,</span></span>
