<span class="line"><span style="color:#56B6C2;">        CAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">d</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">item_id</span><span style="color:#C678DD;"> AS</span><span style="color:#C678DD;"> VARCHAR</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1000</span><span style="color:#ABB2BF;">)) </span><span style="color:#C678DD;">AS</span><span style="color:#C678DD;"> path</span></span>
