<span class="line"><span style="color:#C678DD;">    WHERE</span><span style="color:#D19A66;"> b</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">effective_from</span><span style="color:#56B6C2;"> &lt;=</span><span style="color:#ABB2BF;"> CURRENT_DATE</span></span>
