<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> INDEX</span><span style="color:#61AFEF;"> idx_supply_item_date</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> supply(item_id, available_date) </span><span style="color:#C678DD;">INCLUDE</span><span style="color:#ABB2BF;"> (supply_type, qty, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">);</span></span>
